(function(){'use strict';const version=window.MIYAR_RELEASE?.version||'5.1.0';function setText(node,value){if(node&&node.textContent!==value)node.textContent=value;}function apply(){document.querySelectorAll('.edition').forEach(x=>{if(/v\d|MI.Y.R/i.test(x.textContent))setText(x,'MI’YĀR '+version);});document.querySelectorAll('.main-footer span:first-child').forEach(x=>{const ar=document.documentElement.lang!=='en';setText(x,ar?'معيار '+version+' · ذكاء القوى العاملة':'Miyar '+version+' · Workforce Intelligence');});}let queued=false;function schedule(){if(queued)return;queued=true;setTimeout(()=>{queued=false;apply();},0);}new MutationObserver(schedule).observe(document.documentElement,{subtree:true,childList:true});window.addEventListener('hashchange',schedule);window.addEventListener('miyar:navigate',schedule);document.addEventListener('DOMContentLoaded',schedule);schedule();window.MiyarReleaseVersion={version,apply};})();
